mapper.select:
SELECT r.id, r.name, r.description, r.images, r.duration_days, r.budget, r.category_id, rc.name AS category_name, r.status, r.create_time FROM travel_route r LEFT JOIN route_category rc ON r.category_id = rc.id
r.deleted = 0
AND r.name LIKE CONCAT('%', #{query.name}, '%')
AND r.category_id = #{query.categoryId}
AND r.status = #{query.status}
ORDER BY r.create_time DESC
